    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    colors = set(v for row in grid for v in row if v != bg)

    for color in colors:
        pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        pairs = []
        for i, (r1, c1) in enumerate(pts):
            for r2, c2 in pts[i+1:]:
                if abs(r2-r1) == 1 and abs(c2-c1) == 1:
                    pairs.append(((r1, c1), (r2, c2)))

        if not pairs:
            continue

        # The diagonal pair is a ray seed. Extend away from the rest of
        # the small multicolor figure (the side with fewer nearby marks).
        for (a, b) in pairs:
            (r1, c1), (r2, c2) = a, b
            dr, dc = r2-r1, c2-c1
            ends = [(r1, c1, -dr, -dc), (r2, c2, dr, dc)]
            def nearby(r, c):
                return sum(1 for rr, cc in [(r+dr, c+dc), (r-dr, c-dc)]
                           if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] not in (bg, color))
            # Choose the continuation whose next cell is farther from other colors;
            # ties favor continuing from the later endpoint.
            scores = []
            for r, c, sr, sc in ends:
                rr, cc = r+sr, c+sc
                score = 1 if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg else 0
                score -= nearby(rr, cc) if 0 <= rr < h and 0 <= cc < w else 0
                scores.append(score)
            idx = 1 if scores[1] >= scores[0] else 0
            r, c, sr, sc = ends[idx]
            r, c = r+sr, c+sc
            while 0 <= r < h and 0 <= c < w:
                if out[r][c] == bg:
                    out[r][c] = color
                r += sr
                c += sc
    return out
